CREATE TABLE public.social_reward_challenges (user_id uuid NOT NULL, provider text NOT NULL CHECK (provider IN ('discord','instagram')), code uuid NOT NULL DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,provider), UNIQUE(code));
GRANT SELECT ON public.social_reward_challenges TO authenticated; GRANT ALL ON public.social_reward_challenges TO service_role;
ALTER TABLE public.social_reward_challenges ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own social challenges" ON public.social_reward_challenges FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.social_reward_claims (user_id uuid NOT NULL, provider text NOT NULL CHECK(provider IN ('discord','instagram')), external_id text NOT NULL, hero_id uuid NOT NULL, diamonds integer NOT NULL DEFAULT 50 CHECK(diamonds=50), claimed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,provider), UNIQUE(provider,external_id));
GRANT SELECT ON public.social_reward_claims TO authenticated; GRANT ALL ON public.social_reward_claims TO service_role;
ALTER TABLE public.social_reward_claims ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own social claims" ON public.social_reward_claims FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.social_reward_code(_provider text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid; BEGIN IF auth.uid() IS NULL OR _provider NOT IN ('discord','instagram') THEN RAISE EXCEPTION 'Invalid request'; END IF; INSERT INTO public.social_reward_challenges(user_id,provider) VALUES(auth.uid(),_provider) ON CONFLICT(user_id,provider) DO NOTHING; SELECT code INTO c FROM public.social_reward_challenges WHERE user_id=auth.uid() AND provider=_provider; RETURN c; END $$;
REVOKE ALL ON FUNCTION public.social_reward_code(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.social_reward_code(text) TO authenticated;
CREATE FUNCTION public.award_verified_social(_user uuid,_hero uuid,_provider text,_external text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE h public.heroes; s jsonb; BEGIN IF _provider NOT IN ('discord','instagram') OR nullif(_external,'') IS NULL THEN RAISE EXCEPTION 'Invalid verification'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(_user::text,0)); SELECT * INTO h FROM public.heroes WHERE id=_hero AND user_id=_user FOR UPDATE; IF h.id IS NULL THEN RAISE EXCEPTION 'Character not found'; END IF; IF EXISTS(SELECT 1 FROM public.social_reward_claims WHERE user_id=_user AND provider=_provider) THEN RETURN h.save; END IF; INSERT INTO public.social_reward_claims(user_id,provider,external_id,hero_id) VALUES(_user,_provider,_external,_hero); s:=h.save; IF jsonb_typeof(s->'srv') IS DISTINCT FROM 'object' THEN s:=jsonb_set(s,'{srv}','{}',true); END IF; IF jsonb_typeof(s->'srv'->'premium') IS DISTINCT FROM 'object' THEN s:=jsonb_set(s,'{srv,premium}','{}',true); END IF; s:=jsonb_set(s,'{srv,premium,balance}',to_jsonb(public._num(s->'srv'->'premium'->'balance')+50),true); s:=jsonb_set(s,'{srv,premium,history}',coalesce(s->'srv'->'premium'->'history','[]'::jsonb)||jsonb_build_object('at',now(),'kind','grant','amount',50,'detail','social:'||_provider),true); PERFORM public._write_save(_hero,s); RETURN s; END $$;
REVOKE ALL ON FUNCTION public.award_verified_social(uuid,uuid,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.award_verified_social(uuid,uuid,text,text) TO service_role;